/* The Response Game — readiness platform evaluation build. */
'use strict';
const E=window.TRG_ENGINE,CAT=window.TRG_CATALOG,PATTERNS=window.TRG_PATTERNS,$=s=>document.querySelector(s),esc=E.esc;
const WORKSPACES=[{id:'atlas',name:'Atlas Response · demo'},{id:'civic',name:'Civic Operations · demo'}];
const ICONS={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',library:'<path d="M7 5.667A2.667 2.667 0 0 1 9.667 3h8.666A2.667 2.667 0 0 1 21 5.667v8.666A2.667 2.667 0 0 1 18.333 17H9.667A2.667 2.667 0 0 1 7 14.333z"/><path d="M4.012 7.26A2.005 2.005 0 0 0 3 8.997v10c0 1.1.9 2 2 2h10c.75 0 1.158-.385 1.5-1M11 7h5M11 10h6M11 13h3"/>',campaigns:'<path d="M4 6h16M4 12h10M4 18h6M17 14l4 4-4 4M14 18h7"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 4v2"/>',plans:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5"/>',actions:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 12 3 3 7-7"/>',reports:'<path d="M4 3v18h17M9 16v-5M14 16V7M19 16v-9"/>',integrations:'<path d="M9 3v4M15 3v4M6 7h12v4a6 6 0 0 1-12 0zM12 17v4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',play:'<path d="m8 5 11 7-11 7z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[n]||ICONS.arrow}</svg>`;
const btn=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=(s,type='')=>`<span class="badge ${type}">${esc(s)}</span>`;
const fmtDate=s=>s?new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Not set';
const findScenario=id=>CAT.find(s=>s.id===id)||CAT[0];
let workspace='atlas';try{workspace=localStorage.getItem('trg:workspace')||'atlas';}catch{}
if(!WORKSPACES.some(w=>w.id===workspace))workspace='atlas';
const pendingSaves=new Map(),writeChains=new Map();
let storageBlocked=false;let data,backend=false,search={q:'',sector:'',pattern:'',phase:'',page:1},peopleGroup='Everyone',lastConsequence='',lastTick=Date.now();
function seed(){
 const names=['Morgan Avery','Jordan Ellis','Casey Rowan','Taylor Quinn','Cameron Lane','Riley Brooks','Alex Reed','Sam Parker','Drew Blake','Jamie Cole','Robin Hayes','Devon West'];
 return {schemaVersion:1,configs:{},campaigns:[],runs:[],actions:[],activeRun:null,audit:[],settings:{label:WORKSPACES.find(w=>w.id===workspace).name,timezone:'America/Chicago',quietStart:'20:00',quietEnd:'08:00',retention:90,hold:true},people:names.map((name,i)=>({id:workspace+'-p'+i,external_id:'DEMO-'+(i+1),name,email:'person'+(i+1)+'@example.invalid',role:['Duty officer','Situation coordinator','Resources Unit recorder','Continuity coordinator'][i%4],group:['Incident management team','Crisis leadership','Facilities team'][i%3],department:['Command','Planning','Operations'][i%3],site:workspace==='atlas'?'North Campus':'Municipal center',active:i!==11,smsConsent:i%3===0,voiceConsent:i%4===0})),plans:[{id:'demo-plan-1',name:'Exercise escalation protocol',version:'DEMO-1',section:'§ 4.2',owner:'Demo plan reviewer',status:'Exercise assumption',text:'Acknowledge the initial report, use the current duty contact or designated alternate, preserve unverified facts, and establish the next update. All contacts and thresholds are exercise assumptions.',patterns:['escalate','communicate']},{id:'demo-plan-2',name:'Resource status procedure',version:'DEMO-1',section:'§ 6.1',owner:'Demo plan reviewer',status:'Exercise assumption',text:'Check-in is not proof of capability, fitness or release for assignment. Record unresolved readiness as unverified and route assignment authority to the operational lead.',patterns:['resources','verify']},{id:'demo-plan-3',name:'Continuity and handover protocol',version:'DEMO-1',section:'§ 8.3',owner:'Demo plan reviewer',status:'Exercise assumption',text:'Recommend only authorized interim measures. Retain unresolved dependencies with a named owner and an explicit next verification checkpoint.',patterns:['continuity','handover']}]};
}
function readLocal(){try{const raw=localStorage.getItem('trg:readiness:v1:'+workspace);const d=raw?JSON.parse(raw):seed();if(d.schemaVersion!==1||!Array.isArray(d.people)||!Array.isArray(d.runs))throw Error('Invalid stored schema');return d;}catch(e){storageBlocked=true;toast('Stored legacy data is unreadable. Writes are blocked; use the new pilot or export recovery data.');return seed();}}
function enqueueDatabaseSave(w,snapshot){
 const prior=writeChains.get(w)||Promise.resolve();
 const next=prior.catch(()=>{}).then(async()=>{const r=await fetch('/api/workspaces/'+w+'/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot});if(!r.ok)throw Error('Database rejected save');});
 writeChains.set(w,next);next.catch(()=>toast('Local database save failed; the browser copy is still available.'));return next;
}
function flushDatabase(w){const pending=pendingSaves.get(w);if(pending){clearTimeout(pending.timer);pendingSaves.delete(w);return enqueueDatabaseSave(w,pending.snapshot);}return writeChains.get(w)||Promise.resolve();}
function save(){
 if(storageBlocked)return;
 const w=workspace,snapshot=JSON.stringify(data);
 try{localStorage.setItem('trg:readiness:v1:'+w,snapshot);}catch{toast('Browser storage is unavailable. Export your work before closing this page.');}
 if(backend){const old=pendingSaves.get(w);if(old)clearTimeout(old.timer);const pending={snapshot,timer:setTimeout(()=>{pendingSaves.delete(w);enqueueDatabaseSave(w,snapshot);},150)};pendingSaves.set(w,pending);}
}
function audit(type,detail){data.audit.unshift({id:E.uid('audit'),at:new Date().toISOString(),type,detail});save();}
async function init(){data=readLocal();if(['localhost','127.0.0.1'].includes(location.hostname)){try{const res=await fetch('/api/health');if(res.ok&&(await res.json()).mode==='local-demo'){backend=true;const r=await fetch('/api/workspaces/'+workspace+'/state');const d=await r.json();if(d.state)data=d.state;else save();}}catch{}}render();}
function toast(s){const t=$('#toast');if(!t)return;t.textContent=s;t.classList.add('visible');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('visible'),5000);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function go(page){location.hash='#/'+page;}
function closeDrawer(){const d=$('#drawer');if(d.open)d.close();d.innerHTML='';}
function drawer(title,subtitle,body,foot=''){const d=$('#drawer');d.innerHTML=`<div class="drawer-head"><div><div class="eyebrow">The Response Game</div><h2 id="drawer-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="close-btn" data-action="close" aria-label="Close dialog">×</button></div><div class="drawer-body">${body}</div>${foot?`<div class="drawer-foot">${foot}</div>`:''}`;if(!d.open)d.showModal();}
function head(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow muted">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function completed(){return data.runs.filter(r=>r.status==='completed');}
function wordmark(){return `<span class="wordmark">the response game<small>Organizational readiness</small></span>`;}
function publicPage(){return `<div class="pilot-entry"><header><a class="pilot-brand" href="#/">The Response Game</a><a href="#/pilot/release">System status</a></header><main id="main" tabindex="-1"><p class="pilot-meta">Internal workspace · Browser-only storage</p><h1>Open your workspace</h1><p>Continue assignments, review submitted work and manage actions on this device.</p><div class="pilot-actions">${btn('Open workspace','nav','primary','data-page="pilot"')}</div><p class="pilot-entry-boundary">Public website · no sign-in or access control. Use fictional practice only; do not enter confidential or operational information.</p><details><summary>Earlier workspace records</summary><p>Legacy starter practice is stored separately.</p>${btn('Open legacy records','nav','','data-page="overview"')}</details></main></div>`;}
const NAV=[['pilot','Controlled pilot'],['overview','Overview'],['library','Scenario library'],['campaigns','Campaigns'],['people','People & groups'],['plans','Plans & evidence'],['actions','Improvement actions'],['reports','Reports'],['integrations','Integrations'],['settings','Workspace settings']];
function shell(page,body){return `<div class="shell"><aside class="sidebar" id="sidebar"><a href="#/">${wordmark()}</a><div class="workspace-label">WORKSPACE</div><nav class="nav-list" aria-label="Workspace navigation">${NAV.map(([id,label])=>`<a class="nav-link ${id===page?'active':''}" href="#/${id}" ${id===page?'aria-current="page"':''}>${icon(id)}${label}${id==='library'?'<span class="nav-count">96</span>':id==='actions'&&data.actions.length?`<span class="nav-count">${data.actions.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><span class="badge good">EVALUATION BUILD</span><p>Fictional workspace. Real practice records from this device.<br>No external messages are sent.</p><a class="link" href="#/platform" style="color:#b9d9c2">What is implemented? →</a></div></aside><div class="workspace-main"><header class="topbar"><div class="flex">${btn(icon('menu'),'menu','mobile-menu','aria-label="Toggle navigation" aria-expanded="false"')}<label style="display:none" for="workspace-select">Demo workspace</label><select class="workspace-switch" id="workspace-select">${WORKSPACES.map(w=>`<option value="${w.id}" ${workspace===w.id?'selected':''}>${esc(w.id===workspace?data.settings.label:w.name)}</option>`).join('')}</select>${badge('DEMO')}</div><div class="flex"><span class="statusline"><i class="dot"></i>${backend?'Local database connected':'Browser-only storage'}</span>${btn('Export workspace','export-workspace','small')}<span class="avatar" aria-label="Demo administrator">DA</span></div></header><main class="main-content" id="main" tabindex="-1">${body}</main></div></div>`;}
function metric(label,value,note){return `<div class="card metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;}
function legacyBoundary(){return `<div class="notice flex between wrap mb" data-legacy-boundary><span><strong>Legacy starter workspace</strong> · These counts and records cover legacy starter practice only. Controlled pilot assignments, reviews and verification records are stored separately.</span><a class="btn primary" href="#/pilot/trace">Open controlled pilot evidence</a></div>`;}
function overview(){const runs=completed(),open=data.actions.filter(a=>a.status!=='Verified').length;return head('WORKSPACE / OVERVIEW','Build capability. Not just activity.','Choose a focused responsibility, practice it, and follow the evidence into your next improvement.',btn('Create a campaign '+icon('arrow'),'campaign','primary'))+legacyBoundary()+`<div class="notice flex between wrap mb"><span><strong>New: requirement-to-retest pilot</strong> · Create an assignment, produce work, evaluate evidence and verify a linked transfer retest.</span><a class="btn primary" href="#/pilot">Open controlled pilot</a></div>${data.activeRun?.status==='running'?`<div class="notice flex between wrap mb"><span>Practice in progress: <strong>${esc(data.activeRun.scenarioTitle)}</strong>. Your record is saved.</span>${btn('Resume practice','resume-run','small')}</div>`:''}<div class="summary-grid">${metric('Starter scenarios','96','16 sectors · 6 shared capability patterns')}${metric('Legacy completed practice runs',runs.length,'Legacy starter records only; pilot excluded')}${metric('Open improvement actions',open,'Closure requires evidence and retest')}${metric('People in this workspace',data.people.length,'Fictional contacts · not a connected directory')}</div><section class="focus-banner"><div>${badge('RECOMMENDED FIRST PRACTICE')}<h2>The first ten minutes</h2><p>Own the initial report. Confirm the escalation path. Give the next team something they can trust.</p><div class="mt">${btn('Start the practice '+icon('arrow'),'quick-run','light','data-id="TRG-001"')}</div></div><div class="focus-path"><div><span>01 &nbsp; Plan & authority</span><span>Review</span></div><div class="line"><span></span></div><div><span>02 &nbsp; Decisions & consequences</span><span>Practice</span></div><div class="line"><span></span></div><div><span>03 &nbsp; Evidence & next action</span><span>Improve</span></div></div></section><div class="grid2"><section class="card"><div class="section-head"><div><h2>Capability evidence</h2><p>Rule checks from completed practice. Not an overall readiness score.</p></div>${badge(runs.length?'OBSERVED':'NOT YET ASSESSED',runs.length?'good':'')}</div>${PATTERNS.map(p=>{const r=runs.filter(r=>r.pattern===p.id),checks=r.flatMap(r=>r.observations),met=checks.filter(o=>o.met).length;return `<div class="capability-row"><span>${esc(p.name)}</span>${checks.length?`<div class="flex"><div class="progress-track" aria-label="${met} of ${checks.length} rule checks met"><span style="width:${met/checks.length*100}%"></span></div><span class="small">${met}/${checks.length}</span></div>`:badge('No evidence')}</div>`;}).join('')}</section><section class="card"><div class="section-head"><div><h2>Workspace activity</h2><p>Recorded actions, with their source and time.</p></div></div>${data.audit.length?data.audit.slice(0,6).map(a=>`<div class="activity">${icon('actions')}<div><strong>${esc(a.type)}</strong><p>${esc(a.detail)}</p></div><span class="time">${fmtDate(a.at)}</span></div>`).join(''):empty('Your evidence trail starts here.','Run a simulation or create a campaign. The dashboard updates from your actual activity, not a sample readiness score.',btn('Browse the library','nav','small','data-page="library"'))}</section></div><div class="notice mt">All catalogue content is a review-required starter. Local plan approval, jurisdiction checks and professional evaluation remain necessary before customer rollout.</div>`;}
function scenarioCard(s){return `<article class="card scenario-card clickable"><div class="label-row"><span class="eyebrow">${esc(s.sector)}</span><span class="mono">${s.id}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.objective)}</p><div class="scenario-meta"><span>${s.minutes} min target</span><span>·</span><span>${esc(s.phase)}</span></div><div class="card-footer">${badge('Starter · review required','warn')}${btn('Configure '+icon('arrow'),'configure','small',`data-id="${s.id}"`)}</div></article>`;}
function filtered(){return CAT.filter(s=>(!search.q||[s.title,s.sector,s.role,s.authority,s.authority.includes('Qualified Individual')?'QI alternate':'',s.hazard,s.plan,s.facility,s.department,s.name].join(' ').toLowerCase().includes(search.q.toLowerCase()))&&(!search.sector||s.sector===search.sector)&&(!search.pattern||s.pattern===search.pattern)&&(!search.phase||s.phase.includes(search.phase)));}
function library(){return head('CONTENT / SCENARIO LIBRARY','One library. Many operating realities.','96 sector-specific starters, built from six capability patterns. Configure the context—not the underlying evaluation logic.',btn('Export catalogue','export-catalog'))+legacyBoundary()+`<div class="filters"><label>SEARCH RESPONSIBILITY, HAZARD, PLAN OR FACILITY<input id="library-search" placeholder="Try QI, campus, handover…" value="${esc(search.q)}"></label><label>SECTOR<select id="filter-sector"><option value="">All 16 sectors</option>${[...new Set(CAT.map(s=>s.sector))].map(v=>`<option ${v===search.sector?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>CAPABILITY<select id="filter-pattern"><option value="">All capabilities</option>${PATTERNS.map(p=>`<option value="${p.id}" ${p.id===search.pattern?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>PHASE<select id="filter-phase"><option value="">All phases</option>${['Preparedness','Response','Recovery'].map(v=>`<option ${v===search.phase?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="library-results">${libraryResults()}</div>`;}
function libraryResults(){const rows=filtered(),max=Math.max(1,Math.ceil(rows.length/9));search.page=Math.min(search.page,max);return `<div class="section-head"><span class="small muted">${rows.length} starter templates · 3 bounded condition variants each</span>${btn('Clear filters','clear-filters','small')}</div>${rows.length?`<div class="catalog">${rows.slice((search.page-1)*9,search.page*9).map(scenarioCard).join('')}</div>`:empty('No matching templates.','Try a broader responsibility or clear one of the filters.')}<div class="pagination"><span>Showing ${rows.length?((search.page-1)*9+1):0}–${Math.min(search.page*9,rows.length)} of ${rows.length}</span><div class="flex">${btn('Previous','library-prev','small',search.page<=1?'disabled':'')}<span>Page ${search.page} / ${max}</span>${btn('Next','library-next','small',search.page>=max?'disabled':'')}</div></div>`;}
function configure(id){const s=findScenario(id),c=data.configs[id]||E.defaults(s);drawer(s.title,s.id+' · '+s.name+ ' · version '+s.version,`<p>${esc(s.objective)}</p><div class="notice warn mt">This is a starter exercise, not an approved organization procedure. Changing the role, site or plan reference does not validate the scenario.</div><form id="config-form" data-id="${s.id}"><div class="form-grid"><label>Facility / site<input name="site" maxlength="180" value="${esc(c.site)}" required></label><label>Participant role<input name="role" maxlength="180" value="${esc(c.role)}" required></label><label class="full">Authorized primary / designated alternate<input name="authority" maxlength="180" value="${esc(c.authority)}" required></label><label class="full">Plan and section reference<input name="planRef" maxlength="180" value="${esc(c.planRef)}" required><div class="field-help">Reference metadata only. No plan has been read or validated by entering its name.</div></label><label>Condition variant<select name="variant">${s.variants.map(v=>`<option ${v===c.variant?'selected':''}>${v}</option>`).join('')}</select></label><label>Practice window (3–20 minutes)<input type="number" name="window" min="3" max="20" step="1" value="${c.window}" required></label><label>Delivery preview<select name="channel">${s.channels.map(v=>`<option ${v===c.channel?'selected':''}>${v}</option>`).join('')}</select></label><label>Practice mode<select name="mode"><option ${c.mode==='Coached'?'selected':''}>Coached</option><option ${c.mode==='Observed'?'selected':''}>Observed</option></select></label></div><div class="notice">Locked: scenario objective, evidence requirements, safety boundaries and decision rules. Coached mode shows consequences after each decision; observed mode holds those explanations for the debrief.</div><div id="config-error" class="form-error" role="alert"></div></form>`,btn('Save configuration','save-config')+btn('Save & run preview '+icon('play'),'save-run','primary'));}
function readConfig(){const form=$('#config-form'),o=Object.fromEntries(new FormData(form));o.window=+o.window;o.version=(data.configs[form.dataset.id]?.version||0)+1;const errors=E.validateConfig(o);if(errors.length){$('#config-error').textContent=errors.join(' ');return null;}data.configs[form.dataset.id]=o;audit('Configuration saved',form.dataset.id+' · revision '+o.version);return {id:form.dataset.id,config:o};}
function campaigns(){return head('DELIVERY / CAMPAIGNS','Practice with a purpose and a guardrail.','Define the capability, audience and delivery method. This release previews delivery; it does not schedule or send real communications.',btn('New campaign '+icon('arrow'),'campaign','primary'))+`<div class="summary-grid">${metric('Campaign drafts',data.campaigns.length,'Configured in this workspace')}${metric('Delivery previews',data.campaigns.filter(c=>c.status==='Preview complete').length,'Simulated only; no provider receipts')}${metric('Live channels','0','Provider setup and approval required')}${metric('Safety hold',data.settings.hold?'On':'Off','Sandbox cannot send even when hold is off')}</div>${data.campaigns.length?`<div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Audience</th><th>Delivery</th><th>State</th><th>Control</th></tr></thead><tbody>${data.campaigns.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(findScenario(c.scenarioId).title)}</small></td><td>${esc(c.group)}<small>${c.eligible} eligible · ${c.excluded} excluded at creation</small></td><td>${esc(c.channel)}<small>${esc(c.method)} · ${esc(c.window||'No scheduled dispatch')}</small></td><td>${badge(c.status,c.status==='Preview complete'?'good':'warn')}</td><td>${btn('Preview delivery','preview-campaign','small',`data-id="${c.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No campaigns yet.','Create a draft, choose the people and preview the delivery sequence. You can test exclusions without contacting anyone.',btn('Create a draft','campaign','primary'))}<div class="notice mt">Dispatch safeguards: approved audience, channel consent, quiet hours, message limits, real-incident stop, and an accountable release authority. The public demo deliberately stops before live dispatch.</div>`;}
function campaign(){drawer('Create a campaign','Audience selection and delivery configuration — no real dispatch.',`<form id="campaign-form"><div class="form-grid"><label class="full">Campaign name<input name="name" maxlength="100" placeholder="Duty-team escalation practice" required></label><label class="full">Starter scenario<select name="scenarioId">${CAT.map(s=>`<option value="${s.id}">${s.id} · ${esc(s.title)}</option>`).join('')}</select></label><label>Audience group<select name="group" id="campaign-group"><option>Selected individuals</option><option selected>Everyone</option>${[...new Set(data.people.map(p=>p.group))].map(g=>`<option>${esc(g)}</option>`).join('')}</select></label><label>Delivery channel<select name="channel" id="campaign-channel">${CAT[0].channels.map(v=>`<option>${v}</option>`).join('')}</select></label><label class="full">Individual contacts (used only for “Selected individuals”)<select name="personIds" id="campaign-people" multiple size="4">${data.people.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.role)}</option>`).join('')}</select><div class="field-help">Choose “Selected individuals” above, then select one or more contacts. On desktop, use Ctrl / Command to select more than one.</div></label><label>Rollout method<select name="method"><option>Facilitator launch</option><option>Self-enrollment link</option><option>Scheduled cohort</option><option>Random within approved window</option><option>Plan-change assignment</option><option>Retest after corrective action</option></select></label><label>Proposed window<input name="window" placeholder="e.g. Tuesday shift briefing" maxlength="100"><div class="field-help">Stored as draft intent only; no background scheduler runs.</div></label></div><div id="audience-preview">${audiencePreview('Everyone','Web')}</div><label class="check-label"><input type="checkbox" name="ack" required>I understand this creates a sandbox campaign, not a live notification or an approved exercise.</label><div id="campaign-error" class="form-error" role="alert"></div></form>`,btn('Cancel','close')+btn('Save draft','save-campaign','primary'));}
function audiencePreview(group,channel,ids=null){const a=E.audience(data.people,group,channel,ids);return `<div class="notice"><strong>${a.eligible.length} eligible / ${a.selected.length} selected.</strong> ${a.excluded.length} excluded.<br>${a.excluded.map(p=>`${esc(p.name)}: ${esc(p.reason)}`).join('<br>')||'No audience exclusions in this preview.'}</div>`;}
function previewCampaign(id){const c=data.campaigns.find(c=>c.id===id);if(!c)return;const a=E.audience(data.people,c.group,c.channel,c.recipientIds||null);const blocked=data.settings.hold;c.eligible=a.eligible.length;c.excluded=a.excluded.length;c.status='Preview complete';audit('Delivery preview',c.name+' · '+a.eligible.length+' eligible · no messages sent');drawer(c.name,'Delivery dry run — no actual dispatch.',`<div class="notice ${blocked?'warn':''}"><strong>${blocked?'Safety hold is enabled.':'Safety hold is off.'}</strong> Live transport is not implemented, so this preview cannot send messages in either state.</div><dl class="detail-list"><dt>Scenario</dt><dd>${esc(findScenario(c.scenarioId).title)}</dd><dt>Audience</dt><dd>${esc(c.group)}</dd><dt>Channel</dt><dd>${esc(c.channel)}</dd><dt>Rollout</dt><dd>${esc(c.method)}</dd></dl>${audiencePreview(c.group,c.channel,c.recipientIds||null)}<div class="rule"></div><div class="eyebrow">Proposed message sequence</div><div class="message-box"><div class="message-head">EXERCISE ONLY · PREVIEW</div><p>Exercise from your organization: a response responsibility requires your attention. Acknowledge this exercise, then follow the secure practice link. No operational action is requested.</p></div><div class="timeline-entry">01 · Verify assignment, active employment, policy and channel consent.</div><div class="timeline-entry">02 · Queue a labeled exercise message with a signed assignment link.</div><div class="timeline-entry">03 · Document delivery status separately from acknowledgment.</div><div class="timeline-entry">04 · Route response into the scenario; honor STOP, help, snooze and cancellation.</div><div class="timeline-entry">05 · Close objectives, debrief, preserve evidence and assign follow-up.</div>`,btn('Close','close')+btn('Run participant preview','campaign-run','primary',`data-id="${c.id}"`));renderBackground();}
function people(){const rows=data.people.filter(p=>peopleGroup==='Everyone'||p.group===peopleGroup);return head('ORGANIZATION / PEOPLE & GROUPS','The right people. The right practice.','Fictional personnel records for demonstration. SSO authenticates users; directory provisioning is a separate integration.',btn('Import demo CSV','import-people','primary'))+`<div class="group-tabs">${['Everyone',...new Set(data.people.map(p=>p.group))].map(g=>`<button class="${g===peopleGroup?'selected':''}" data-action="people-group" data-group="${esc(g)}">${esc(g)} · ${data.people.filter(p=>g==='Everyone'||p.group===g).length}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Person / source ID</th><th>Role / department</th><th>Group / site</th><th>Eligibility</th><th>Record</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.external_id)} · ${esc(p.email)}</small></td><td>${esc(p.role)}<small>${esc(p.department)}</small></td><td>${esc(p.group)}<small>${esc(p.site)}</small></td><td>${badge(p.active?'Active':'Inactive',p.active?'good':'')}<small>SMS ${p.smsConsent?'consent example':'not opted in'} · Voice ${p.voiceConsent?'consent example':'not opted in'}</small></td><td>${btn('Manage','person','small',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="notice mt">Do not preload real personnel or confidential information into this public demonstration. Sample consent flags illustrate eligibility rules; they are not legal consent records.</div>`;}
function managePerson(id){const p=data.people.find(p=>p.id===id);drawer(p.name,'Demo personnel record — edits remain in this workspace.',`<form id="person-form" data-id="${p.id}"><div class="form-grid"><label>Group<input name="group" value="${esc(p.group)}" maxlength="100" required></label><label>Role<input name="role" value="${esc(p.role)}" maxlength="100" required></label><label>Department<input name="department" value="${esc(p.department)}" maxlength="100" required></label><label>Site<input name="site" value="${esc(p.site)}" maxlength="100" required></label></div><label class="check-label"><input type="checkbox" name="active" ${p.active?'checked':''}>Active personnel record</label><div class="notice">Changing a group does not grant permissions or consent. Live access roles and eligibility must be enforced by a trusted server.</div><div id="person-error" class="form-error"></div></form>`,btn('Save record','save-person','primary'));}
function importPeople(){drawer('Import demo personnel','CSV validation with explicit exceptions; no silent merging.',`<p>Use fictional contacts only. Required columns: external_id, name, email, group, role. Optional: department, site. Imported contacts receive no SMS or voice consent.</p><div class="mt">${btn('Download CSV template','people-template','small')}</div><label class="mt">Choose a CSV file<input type="file" id="people-file" accept=".csv,text/csv"></label><label class="mt">Or paste CSV<textarea id="people-csv" rows="6" placeholder="external_id,name,email,group,role"></textarea></label><div id="import-result" class="mt"></div>`,btn('Validate','validate-people')+btn('Import accepted records','commit-people','primary','disabled id="commit-people"'));}
let pendingImport=null;
function plans(){return head('GOVERNANCE / PLANS & EVIDENCE','The gold thread starts in the plan.','Keep each requirement connected to its source, exercise objective, evidence, finding and verification.',btn('Add plan excerpt','add-plan','primary'))+`<div class="notice warn mb">The included excerpts are authored exercise assumptions. No organization plan has been uploaded, extracted or independently validated.</div><div class="grid2">${data.plans.map(p=>`<article class="card plan-card"><div class="flex between">${badge(p.status,'warn')}<span class="mono small">${esc(p.version)}</span></div><h3 class="mt">${esc(p.name)}</h3><p class="small muted" style="margin-top:9px">${esc(p.section)} · ${esc(p.owner)}</p><blockquote>${esc(p.text)}</blockquote><div class="trace"><span>Plan section</span>→<span>Objective</span>→<span>Evidence</span>→<span>Action</span></div><div class="rule"></div><div class="small muted">${p.patterns.map(x=>esc(PATTERNS.find(p=>p.id===x)?.name||x)).join(' · ')}</div></article>`).join('')}</div>`;}
function addPlan(){drawer('Add a plan-source excerpt','Metadata and text entry; this is not an automated document-ingestion service.',`<form id="plan-form"><div class="form-grid"><label class="full">Plan title<input name="name" required maxlength="180"></label><label>Source version<input name="version" required maxlength="50"></label><label>Section / page<input name="section" required maxlength="70"></label><label class="full">Reviewer / owner<input name="owner" required maxlength="100"></label><label class="full">Requirement excerpt<textarea name="text" required minlength="20" maxlength="4000"></textarea></label><label class="full">Capability mapping<select name="pattern">${PATTERNS.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label></div><div class="notice warn">Do not enter sensitive plans in this public demo. New excerpts remain “Review required”; typing an owner’s name does not constitute approval.</div><div id="plan-error" class="form-error"></div></form>`,btn('Save excerpt','save-plan','primary'));}
function actions(){const buckets=[['Open','Open / assigned'],['Verification requested','Awaiting verification'],['Verified','Verified']];return head('IMPROVEMENT / ACTIONS','A finding is not a finished improvement.','Keep the source observation, owner, due date, evidence and retest together. No automatic closure from participation.',btn('Create action','new-action','primary'))+`<div class="kanban">${buckets.map(([k,label])=>{const a=data.actions.filter(a=>k==='Open'?!['Verification requested','Verified'].includes(a.status):a.status===k);return `<section class="kanban-col"><div class="section-head"><h3>${label}</h3>${badge(String(a.length))}</div>${a.length?a.map(a=>`<article class="action-card"><span class="mono small muted">${esc(a.shortId)}</span><h3>${esc(a.title)}</h3><p>${esc(a.owner||'Owner not assigned')} · ${a.due?esc(a.due):'Due date not set'}</p><p style="margin-top:8px">${esc(a.sourceRun?'Linked to '+a.sourceRun.slice(0,12):'Manually recorded; source not yet linked')}</p>${btn('Review action','edit-action','small',`data-id="${a.id}"`)}</article>`).join(''):'<p class="small muted">No actions in this state.</p>'}</section>`;}).join('')}</div><div class="notice mt">Legacy action verification is disabled. Use the Controlled pilot for evaluator decisions, findings and linked transfer retest verification. Existing records remain historical, unvalidated demo entries.</div>`;}
function actionForm(id='',runId=''){let a=data.actions.find(a=>a.id===id),r=data.runs.find(r=>r.id===runId);if(!a)a={id:'',title:r?'Review '+(r.observations.find(o=>!o.met)?.criterion||'the submitted exercise brief'):'',owner:'',due:'',status:'Open',sourceRun:r?.id||'',pattern:r?.pattern||'escalate',evidence:'',reviewer:'',retestId:''};drawer(a.id?'Review improvement action':'Create improvement action','Preserve the source. Define the verification.',`<form id="action-form" data-id="${esc(a.id)}"><input type="hidden" name="sourceRun" value="${esc(a.sourceRun)}"><div class="form-grid"><label class="full">Action / intended improvement<input name="title" value="${esc(a.title)}" maxlength="250" required></label><label>Owner<input name="owner" value="${esc(a.owner)}" maxlength="100"></label><label>Due date<input name="due" type="date" value="${esc(a.due)}"></label><label>Capability<select name="pattern">${PATTERNS.map(p=>`<option value="${p.id}" ${p.id===a.pattern?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Status<select name="status">${['Open','Assigned','In progress','Verification requested','Verified'].map(v=>`<option ${v===a.status?'selected':''}>${v}</option>`).join('')}</select></label><label class="full">Completion evidence / verification basis<textarea name="evidence" maxlength="3000">${esc(a.evidence)}</textarea></label><label>Verification reviewer<input name="reviewer" value="${esc(a.reviewer)}" maxlength="100"></label><label>Retest evidence<select name="retestId"><option value="">Select a completed run</option>${completed().filter(r=>r.id!==a.sourceRun).map(r=>`<option value="${r.id}" ${r.id===a.retestId?'selected':''}>${esc(r.scenarioTitle)} · ${E.summary(r).met}/3</option>`).join('')}</select></label></div><div class="notice">“Verified” is blocked without its required fields and a successful matching-capability retest. Free-text response quality still needs professional review.</div><div id="action-error" class="form-error" role="alert"></div></form>`,btn('Save action','save-action','primary'));}
function reports(){const r=completed(),obs=r.flatMap(x=>x.observations),met=obs.filter(o=>o.met).length;return head('EVIDENCE / REPORTS','Evidence you can inspect.','Rule checks, written responses and time records are separate. No blended readiness score, invented benchmark or cross-role leaderboard.',btn('Export evidence CSV','export-evidence'))+legacyBoundary()+`<div class="summary-grid">${metric('Legacy completed runs',r.length,'Legacy starter records only; pilot excluded')}${metric('Rule checks met',obs.length?met+' / '+obs.length:'—','Deterministic checks, not validated competence')}${metric('Written briefs needing review',r.length,'No automated free-text correctness scoring')}${metric('Linked retest attempts',r.filter(x=>x.previousId).length,'Earlier attempts remain in the record')}</div><div class="card"><div class="section-head"><h2>Completed practice records</h2>${badge('THIS WORKSPACE')}</div>${r.length?r.slice().reverse().map(x=>`<div class="report-row flex between wrap"><div><strong>${esc(x.scenarioTitle)}</strong><p>${esc(x.config.role)} · ${esc(x.config.variant)} · ${fmtDate(x.completedAt)} · ${E.summary(x).met}/3 rule checks</p></div>${btn('Open debrief','report','small',`data-id="${x.id}"`)}</div>`).join(''):empty('No completed practice yet.','Finish a micro-simulation to generate an inspectable evidence record.',btn('Choose a scenario','nav','primary','data-page="library"'))}</div>`;}
const INTEGRATIONS=[['Organization database','Supabase / PostgreSQL','Tenant-separated records, identity, row-level access controls and private storage.','Database project provisioning, deployed schema and tenant-isolation tests.'],['Single sign-on','SAML / organizational identity','Authenticate participants using an approved identity provider. SSO does not load or maintain a complete personnel roster.','Identity-provider metadata, verified domains, claim mapping, role policy and session-revocation tests.'],['Personnel directory','SCIM / approved personnel API','Provision, update, suspend and group personnel from a trusted source.','Data owner approval, field mapping, source IDs, conflict review, sync rules and deprovisioning tests.'],['SMS & voice','Telephony provider adapter','Send labeled exercise traffic, receive replies and route them to the same scenario state machine.','Provider account, sender registration, consent records, recording policy, verified webhooks and sandbox tests.'],['Email & collaboration','Email / Teams / enterprise messaging','Deliver an assignment, capture engagement and move the learner into secure practice.','Approved sender, provider authentication, signed one-time links, bounce policy and tenant binding.'],['External task systems','Training forms / LMS / ticketing API','Collect completion evidence from an approved training system without touching live operational workflows.','Test-only endpoint, signed event schema, assignment identity, replay protection and completion evidence contract.']];
function integrations(){return head('PLATFORM / INTEGRATIONS','Connected by design. Honest about status.','The production integration contracts are specified. No live organization database, directory or communication provider is connected in this public build.')+`<div class="grid3">${INTEGRATIONS.map((x,i)=>`<article class="card integration-card"><div class="flex">${icon('integrations')}${badge('Not connected','warn')}</div><h3>${x[0]}</h3><span class="small muted">${x[1]}</span><p style="margin-top:12px">${x[2]}</p>${btn('View connection requirements','integration','small',`data-index="${i}"`)}</article>`).join('')}</div><div class="notice mt">A connector icon is not a connection. Live credentials belong in a server-side secret store, never this page, exported configuration, source control or browser storage.</div>`;}
function settings(){return head('GOVERNANCE / WORKSPACE SETTINGS','Bounded configuration. Visible controls.','Demonstrate tenant-level rules without creating unsupported custom workflows or hiding the safety state.')+`<form id="settings-form" class="settings-grid"><section class="card"><h2 style="font-size:18px">Workspace defaults</h2><div class="form-grid"><label class="full">Workspace label<input name="label" value="${esc(data.settings.label)}" maxlength="100" required></label><label class="full">Time zone<select name="timezone">${['America/Chicago','America/New_York','America/Los_Angeles','Europe/London','UTC'].map(v=>`<option ${v===data.settings.timezone?'selected':''}>${v}</option>`).join('')}</select></label><label>Quiet hours begin<input name="quietStart" type="time" value="${data.settings.quietStart}" required></label><label>Quiet hours end<input name="quietEnd" type="time" value="${data.settings.quietEnd}" required></label><label class="full">Proposed retention (days)<input name="retention" type="number" min="7" max="3650" value="${data.settings.retention}"><div class="field-help">Design setting only. The demo does not automatically delete retained evidence.</div></label></div></section><section class="card"><h2 style="font-size:18px">Exercise safety</h2><label class="check-label"><input type="checkbox" name="hold" ${data.settings.hold?'checked':''}>Organization-wide exercise hold</label><p class="small muted">In production this stops queued delivery, follow-ups and automation. In this sandbox, all external transport is disabled regardless of this setting.</p><div class="rule"></div><div class="notice warn">This is not an emergency notification system. Never place exercise calls to emergency services, regulators or unapproved third parties.</div><div class="mt">${btn('Save workspace settings','save-settings','primary')}</div></section></form>`;}
function platform(){return head('PRODUCT / RELEASE BOUNDARIES','A readiness platform, not a claim of readiness.','This release replaces the old game with a usable evaluation workspace and a concrete enterprise delivery design.')+`<div class="grid2"><section class="card"><h2>Implemented in this build</h2><div class="checklist">Catalogue filtering and controlled configuration.<br>96 starter scenarios across 16 sectors and 6 patterns.<br>3 condition variants; 5 channel presentation modes.<br>Branching consequences, structured briefs and debriefs.<br>People groups, CSV validation and import exceptions.<br>Campaign audience preview and eligibility exclusions.<br>Plan-source excerpts and linked improvement actions.<br>Retest links, workspace switching and evidence export.<br>Local browser persistence; optional local demo database.</div></section><section class="card"><h2>Not represented as live</h2><div class="checklist">Licensed customer provisioning or billing.<br>Production database tenancy or authenticated access.<br>SSO / SCIM directory synchronization.<br>Real email, SMS, phone calls or recordings.<br>Background campaign scheduling or orchestration.<br>Automated plan ingestion or AI evaluation.<br>External-tool completion webhooks.<br>Validated competency scores or compliance credit.<br>Independent accessibility or human-factors acceptance.</div></section></div><section class="card mt"><h2>Configure the context. Govern the engine.</h2><p class="small muted mt">Site names, role aliases, approved authority references, allowed variants, bounded practice windows, delivery preferences and audience selection are configuration. New workflow primitives, custom interfaces, bespoke integrations or altered scoring logic require product change control, not a hidden customer-specific fork.</p></section>`;}
function render(){if(!data)return;if(location.hash.startsWith('#/pilot')){$('#app').innerHTML='<div class="pilot-shell"><div id="pilot-root"><p>Opening workspace…</p></div></div>';document.title='The Response Game';window.TRG_PILOT?.mount().then(()=>{if(location.hash.startsWith('#/pilot'))$('#main')?.focus({preventScroll:true});});return;}const path=location.hash.replace(/^#\/?/,'').split('/'),page=path[0]||'';document.title='The Response Game · '+(NAV.find(n=>n[0]===page)?.[1]||'Organizational readiness');if(page==='run'){if(!data.activeRun){go('library');return;}$('#app').innerHTML=player();}else if(page==='report'){const r=data.runs.find(r=>r.id===path[1]);$('#app').innerHTML=r?playerFrame(debrief(r)):shell('reports',reports());}else if(!page){$('#app').innerHTML=publicPage();}else {const view={overview,library,campaigns,people,plans,actions,reports,integrations,settings,platform}[page]||overview;$('#app').innerHTML=shell(page,view());}window.scrollTo(0,0);lastTick=Date.now();}
function renderBackground(){if(location.hash.includes('campaigns')){$('#app').innerHTML=shell('campaigns',campaigns());}}
function startRun(id,c=null,previousId=null){const s=findScenario(id),config=c||data.configs[s.id]||E.defaults(s);if(data.activeRun?.status==='running'){data.activeRun.status='abandoned';E.record(data.activeRun,'abandoned',{reason:'A new preview was started'});data.runs.push(data.activeRun);}data.activeRun=E.createRun(s,config,previousId);E.record(data.activeRun,'exercise_started',{channel:config.channel,delivery:'Local simulation; no external message'});lastConsequence='';audit('Practice started',s.id+' · '+s.title);closeDrawer();if(location.hash==='#/run')render();else go('run');}
function clock(ms){const s=Math.floor(ms/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function playerFrame(body){const r=data.activeRun;return `<div class="player-shell"><header class="player-top"><a href="#/overview">${wordmark()}</a><div class="player-clock">${r?.status==='running'?`<span>Active practice &nbsp; <strong id="active-clock">${clock(r.activeMs)}</strong></span><span>Scenario clock &nbsp; <strong>${r.elapsedSim} / ${r.config.window} min</strong></span>`:''}</div><div class="flex">${r?.status==='running'?btn(r.paused?'Resume':'Pause','pause','small'):''}${btn('Return to workspace','exit-player','small')}</div></header><div class="exercise-ribbon">EXERCISE ONLY · FICTIONAL CONDITIONS · NO REAL MESSAGES OR OPERATIONAL ACTIONS</div><main class="player-main" id="main">${body}</main></div>`;}
function player(){const r=data.activeRun,s=r.scenarioSnapshot||findScenario(r.scenarioId),names=['Receive & respond','Verify the evidence','Take the action','Record the handover'];if(r.status==='completed')return playerFrame(debrief(r));return playerFrame(`<div class="player-layout"><aside class="player-sidebar">${badge(r.config.mode.toUpperCase()+' PRACTICE')}<h2>${esc(s.title)}</h2><p>${esc(s.objective)}</p><div class="rule"></div><div class="eyebrow" style="color:#a9c3c1">YOUR ROLE</div><p style="margin-top:8px;color:#e1ece6">${esc(r.config.role)}<br>${esc(r.config.site)}</p><div class="step-list">${names.map((n,i)=>`<div class="step-item ${i===r.step?'current':''}" ${i===r.step?'aria-current="step"':''}><span class="num">${i<r.step?'✓':i+1}</span><span>${n}</span></div>`).join('')}</div><div class="rule"></div><p>Condition: ${esc(r.config.variant)}<br>Channel: ${esc(r.config.channel)}<br>Target: ${r.config.window} minutes<br>Free-text work receives human review.</p></aside><section class="card player-card">${r.paused?`<div class="pause-overlay"><div class="eyebrow muted">PRACTICE PAUSED</div><h1>Take the time you need.</h1><p>Active time and scenario progression are paused. Your record remains in this workspace. This is a training environment, not a real emergency.</p>${btn('Resume practice','pause','primary')}</div>`:playerStep(r,s)}</section></div>`);}
function consequence(r){if(!r.observations.length||r.config.mode!=='Coached')return '';const o=r.observations.at(-1);return `<div class="consequence"><strong>Consequence recorded.</strong> ${esc(o.reason)} ${o.met?'The next action can build on this record.':'This gap remains in the evidence even if you correct course.'}</div>`;}
function choice(id,title,text,i){return `<button class="choice" data-action="decision" data-choice="${id}"><span class="key">${i+1}</span><span><strong>${esc(title)}</strong><p>${esc(text)}</p></span></button>`;}
function sourceCards(r,s){const missed=r.observations[0]&&!r.observations[0].met,alt=r.config.variant==='Primary unavailable',conflict=r.config.variant==='Conflicting reports';return `<div class="evidence-card"><div class="flex between">${badge('A · CURRENT RECORD','good')}<span class="mono small">T+${missed?'04':'01'}</span></div><h3>Attributable duty-team update</h3><p>${esc(r.config.site)}: the disruption report has been received; its full impact remains unverified. ${esc(s.resource)} is reported but capability and release for assignment are not confirmed. ${alt?'The primary duty contact is unavailable. The designated alternate is the documented escalation path.':'The current duty contact is reachable through the approved exercise channel.'} ${conflict?'A second source disputes the affected location; neither location is confirmed.':'The initial affected area remains provisional.'}</p></div><div class="evidence-card"><div class="flex between">${badge('B · SUPERSEDED RECORD')}<span class="mono small">T−60</span></div><h3>Previous shift summary</h3><p>All support resources were listed available at the last shift change. No current disruption was recorded. This record predates the present report.</p></div><div class="evidence-card"><div class="flex between">${badge('C · UNATTRIBUTED REPORT','warn')}<span class="mono small">Time unknown</span></div><h3>Forwarded message</h3><p>“It is all under control. Everything should be back shortly.” The message has no identified source, verification status or approved restoration estimate.</p></div>`;}
function playerStep(r,s){let html=consequence(r);if(r.step===0){html+=`<div class="eyebrow muted">STEP 01 / RECEIVE & RESPOND</div><h1>The report is incomplete.<br>Your responsibility is not.</h1><p>Acknowledge and establish an accountable response path. You are not being asked to take real operational action.</p><div class="message-box"><div class="message-head"><span>${esc(r.config.channel.toUpperCase())} · EXERCISE SIMCELL</span><span>T+00:00</span></div><p>${esc(s.trigger.replace(s.site,r.config.site))}</p><p style="margin-top:12px">${r.config.variant==='Primary unavailable'?'The primary contact does not answer; a designated alternate is listed in the exercise protocol.':r.config.variant==='Conflicting reports'?'Two sources describe different affected areas. No cause, full impact or recovery estimate is verified.':'The full impact is not yet confirmed. The current duty contact is available.'}</p></div>`;
 if(r.config.channel==='SMS preview')html+=`<div class="notice">SMS sandbox: type ACK, DETAILS or LATER. HELP pauses for guidance; STOP ends this local exercise without a failure score. No text is transmitted.</div><div class="flex mt"><label style="flex:1">Your reply<input id="sms-reply" placeholder="ACK / DETAILS / LATER / HELP / STOP" maxlength="40"></label>${btn('Respond','sms-reply','primary')}</div>`;
 else {if(r.config.channel==='Voice preview')html+=`<div class="notice">Local voice preview: browser narration only. No phone call, microphone capture or voice recording occurs.</div><div class="mt">${btn('Listen to the exercise prompt','narrate','small')}</div>`;html+=`<div class="options">${choice('ack','Acknowledge and route the initial report','Use the designated duty channel. Preserve unknowns rather than waiting for a complete picture.',0)}${choice('clarify','Acknowledge while requesting the missing facts','Maintain ownership while obtaining the current source, location and impact information.',1)}${choice('defer','Wait for a complete incident picture before responding','No one has yet acknowledged ownership of the initial report.',2)}</div>`;}
 return html;}
 if(r.step===1)return html+`<div class="eyebrow muted">STEP 02 / VERIFY THE EVIDENCE</div><h1>Which record can you build on?</h1><p>Your first decision has moved the scenario clock to T+${r.elapsedSim}. Compare the source, time and limits before selecting the controlling record.</p>${sourceCards(r,s)}<div class="options">${choice('old','Use the previous shift summary','It offers a complete and familiar resource picture, but predates the incident.',0)}${choice('current','Use the current attributable update','Retain its explicit unknowns and current contact availability.',1)}${choice('rumor','Use the forwarded message','It suggests the situation is contained but has no verified source.',2)}</div>`;
 if(r.step===2){const valid={escalate:['authority',r.config.variant==='Primary unavailable'?'Route through the designated alternate':'Route through the current authorized duty contact','Preserve the initial facts and identify the next update point.'],verify:['verified','Publish only the attributable facts, with the gaps visible','Retain source and time; label the disputed location or impact as unverified.'],continuity:['bounded','Recommend an authorized interim measure with a review checkpoint','Identify dependencies and ask the responsible lead to decide within the approved plan.'],resources:['unverified','Record readiness as unverified; seek operational authorization','Check-in or an old availability list does not establish current deployable capacity.'],communicate:['review','Prepare a holding line for the approved review path','State verified information and the next update, without promising a cause or restoration time.'],handover:['open','Transfer the unresolved condition with an owner and checkpoint','Do not close an issue merely because the shift is ending.']}[r.pattern];
 return html+`<div class="eyebrow muted">STEP 03 / TAKE THE ACTION</div><h1>${esc(s.task)}</h1><p>Your record now affects the action. ${r.config.mode==='Observed'?'A new duty update is available. Use the current exercise record before committing.':r.observations[1]?.met?'You retained a current source and visible uncertainty.':'You relied on an unsupported source. The updated record below is an opportunity to correct course; the earlier evidence remains.'}</p><div class="evidence-card"><div class="eyebrow muted">AUTHORITATIVE EXERCISE EXCERPT · NOT AN ORGANIZATION PLAN</div><h3>${esc(r.config.planRef)}</h3><p>Use the designated primary or alternate: ${esc(r.config.authority)}. The full impact, current resource readiness and restoration time remain unverified. Keep decisions within delegated authority and record the next checkpoint. This excerpt is a starter assumption, not extracted plan text.</p></div>${r.pattern==='continuity'?`<div class="sim-map" aria-label="Schematic exercise map, not geographic or operational information"><div class="map-zone affected">Zone A<br>Reported disruption<br><strong>Impact unverified</strong></div><div class="map-zone">Zone B<br>Potential alternate support<br><strong>Capacity unverified</strong></div></div><p class="field-help">Schematic training artifact only. It does not establish evacuation routes or safe access.</p>`:''}${r.config.channel==='External-task preview'?`<div class="notice mt">External-task preview: open the training worksheet and record the reference below. A manual reference is self-reported evidence, not verified completion in an external system.</div><div class="mt">${btn('Open practice worksheet','worksheet','small')}</div>`:''}<form id="task-form" class="mt"><label>Record the action posture<select name="choice" required><option value="">Choose an action based on the supplied evidence</option><option value="assume">Treat the prior assumptions as confirmed and proceed without further authorization</option><option value="${valid[0]}">${esc(valid[1])}</option><option value="delay">Defer the task without an accountable interim action</option></select></label><p class="field-help">${esc(valid[2])}</p><div class="form-grid"><label>Accountable role / recipient<input name="recipient" maxlength="150" required placeholder="Use the role in the exercise protocol"></label><label>Next update checkpoint<input name="checkpoint" maxlength="100" required placeholder="e.g. next duty update in 5 minutes"></label>${r.config.channel==='External-task preview'?'<label class="full">Training worksheet reference<input name="externalRef" maxlength="150" required placeholder="Self-reported worksheet reference"></label>':''}</div><div id="task-error" class="form-error" role="alert"></div>${btn('Commit the action '+icon('arrow'),'submit-task','primary')}</form>`;}
 return html+`<div class="eyebrow muted">STEP 04 / RECORD THE HANDOVER</div><h1>Give the next person a usable record.</h1><p>Separate verified information, unresolved questions and the next action. This is a real writing task; it is captured for human review rather than judged by keywords. Recipient and checkpoint text from the preceding task also require review.</p><form id="brief-form" class="mt"><label>What is known?<textarea name="known" minlength="10" maxlength="3000" required placeholder="Identify the current source, time and facts.">${esc(r.draft?.known||'')}</textarea></label><label class="mt">What remains unknown?<textarea name="unknown" minlength="10" maxlength="3000" required placeholder="State the gaps and the limits of the information.">${esc(r.draft?.unknown||'')}</textarea></label><label class="mt">What happens next, by whom, and when?<textarea name="next" minlength="10" maxlength="3000" required placeholder="Name the responsible role, action and next checkpoint.">${esc(r.draft?.next||'')}</textarea></label><div class="notice mt">Record quality needs professional review. Fast completion is not the same as correct performance. Pauses and active practice time remain distinct from the scenario clock.</div><div id="brief-error" class="form-error" role="alert"></div>${btn('Complete & review evidence '+icon('arrow'),'complete-run','primary')}</form>`;
}
function debrief(r){const q=E.summary(r);return `<div class="debrief"><div class="eyebrow muted">AFTER-ACTION PRACTICE RECORD / ${esc(r.scenarioId)}</div><h1>${esc(r.scenarioTitle)}</h1><p>${esc(r.config.role)} · ${esc(r.config.site)} · ${esc(r.config.variant)} · ${esc(r.config.mode)}<br>Scenario v${esc(r.scenarioVersion)} · configuration revision ${r.config.version||1} · ${fmtDate(r.completedAt)}</p><div class="summary-grid">${metric('Rule checks met',q.met+' / '+q.observed,'Starter criteria, not validated competence')}${metric('Written brief','Review','Captured; not automatically graded')}${metric('Active practice',clock(r.activeMs),'Excludes recorded pauses')}${metric('Scenario clock',r.elapsedSim+' min',q.windowMet?'Within configured exercise window':'Beyond configured exercise window')}</div><div class="notice warn mb">This record is evidence of this practice attempt, not a certification of individual or organizational readiness. The scripted checks and your written brief require professional interpretation.</div><section class="card"><h2>What the practice showed</h2>${r.observations.map(o=>`<div class="observation"><span class="result ${o.met?'':'fail'}">${o.met?'✓':'!'}</span><div><h3>${esc(o.criterion)}</h3><p>${esc(o.reason)}</p><p class="mono" style="font-size:9px;margin-top:8px">Evidence ${esc(o.evidenceId)}</p></div></div>`).join('')}</section><section class="card mt"><div class="section-head"><h2>Your handover record</h2>${badge('Human review required','warn')}</div>${['known','unknown','next'].map((k,i)=>`<div class="report-row"><strong>${['Known information','Unresolved information','Next action, owner and checkpoint'][i]}</strong><p style="white-space:pre-wrap">${esc(r.draft[k])}</p></div>`).join('')}</section><section class="card mt"><div class="section-head"><h2>Inspect the decision trail</h2><span class="small muted">${r.events.length} recorded events</span></div><details><summary class="small" style="cursor:pointer">Show event-level evidence</summary>${r.events.map(e=>`<div class="timeline-entry"><span class="mono">#${e.sequence} · ${esc(e.at)} · ${esc(e.type)}</span><br>${esc(e.payload.reason||e.payload.criterion||e.payload.status||e.payload.channel||'Record captured')}</div>`).join('')}</details><div class="trace"><span>${esc(r.config.planRef)}</span>→<span>${esc(r.scenarioId)}</span>→<span>${r.observations.length} rule checks</span>→<span>Human review</span></div></section><div class="flex wrap mt no-print">${btn('Create improvement action','action-from-run','primary',`data-id="${r.id}"`)}${btn('Retest with another condition','retest','',`data-id="${r.id}"`)}${btn('Export JSON','export-run','',`data-id="${r.id}"`)}${btn('Print / save PDF','print')}</div></div>`;}
function advance(id){const r=data.activeRun;try{lastConsequence=E.choose(r,r.step,id);save();render();}catch(e){toast(e.message);}}
function formObject(selector){const f=$(selector);if(!f.reportValidity())return null;return Object.fromEntries(new FormData(f));}
function showFormError(selector,e){const n=$(selector);if(n)n.textContent=e.message||e;else toast(String(e.message||e));}
function saveCampaign(){const x=formObject('#campaign-form');if(!x)return;const recipientIds=x.group==='Selected individuals'?new FormData($('#campaign-form')).getAll('personIds'):null;const a=E.audience(data.people,x.group,x.channel,recipientIds);if(!a.eligible.length){showFormError('#campaign-error','No eligible recipients. Change the audience or channel.');return;}delete x.personIds;const c={...x,recipientIds,id:E.uid('campaign'),eligible:a.eligible.length,excluded:a.excluded.length,status:'Draft',createdAt:new Date().toISOString(),scenarioVersion:findScenario(x.scenarioId).version,config:JSON.parse(JSON.stringify(data.configs[x.scenarioId]||E.defaults(findScenario(x.scenarioId))))};delete c.ack;data.campaigns.unshift(c);audit('Campaign drafted',c.name+' · no dispatch scheduled');closeDrawer();go('campaigns');render();toast('Campaign draft saved. No messages sent or scheduled.');}
function saveAction(){const x=formObject('#action-form');if(!x)return;const id=$('#action-form').dataset.id;let old=data.actions.find(a=>a.id===id);if(x.status==='Verified'){showFormError('#action-error',Error('Legacy verification is disabled. Use the controlled pilot with an evaluator and linked retest.'));return;}if(x.status!=='Open'&&(!x.owner||!x.due)){showFormError('#action-error','Assign an owner and due date before advancing the status.');return;}if(x.status==='Verification requested'&&!x.evidence.trim()){showFormError('#action-error','Completion evidence is required before requesting verification.');return;}if(x.status==='Verified'&&(!E.canVerify(x,data.runs)||x.retestId===x.sourceRun)){showFormError('#action-error','Verification requires an owner, due date, evidence, reviewer and a separate completed matching-capability retest with all three checks met.');return;}if(old){Object.assign(old,x);old.history.push({at:new Date().toISOString(),status:x.status,evidence:x.evidence});}else data.actions.push({...x,id:E.uid('action'),shortId:'ACT-'+String(data.actions.length+1).padStart(3,'0'),createdAt:new Date().toISOString(),history:[{at:new Date().toISOString(),status:x.status,evidence:x.evidence}]});audit('Improvement action saved',x.title+' · '+x.status);closeDrawer();go('actions');render();toast('Action and status history saved.');}
function exportEvidence(){const rows=[['Workspace','Run ID','Scenario ID','Title','Pattern','Mode','Variant','Started','Completed','Active seconds','Scenario minutes','Criterion','Met','Evidence event','Written review']];completed().forEach(r=>r.observations.forEach(o=>rows.push([workspace,r.id,r.scenarioId,r.scenarioTitle,r.pattern,r.config.mode,r.config.variant,r.startedAt,r.completedAt,Math.round(r.activeMs/1000),r.elapsedSim,o.criterion,o.met?'Yes':'No',o.evidenceId,'Human review required'])));download('TRG_evidence_'+workspace+'.csv',E.csv(rows),'text/csv;charset=utf-8');}
async function handleAction(action,el){
 const id=el.dataset.id;
 if(action==='nav'){go(el.dataset.page);return;}
 if(action==='close'){closeDrawer();return;}
 if(action==='menu'){const on=$('#sidebar').classList.toggle('open');el.setAttribute('aria-expanded',String(on));return;}
 if(action==='resume-run'){data.activeRun.paused=false;E.record(data.activeRun,'resume',{reason:'Resumed from workspace'});save();go('run');return;}
 if(action==='quick-run'){startRun(id);return;}
 if(action==='configure'){configure(id);return;}
 if(action==='save-config'||action==='save-run'){const o=readConfig();if(o){if(action==='save-run')startRun(o.id,o.config);else{closeDrawer();toast('Configuration saved. Core decision rules remain unchanged.');}}return;}
 if(action==='clear-filters'){search={q:'',sector:'',pattern:'',phase:'',page:1};render();return;}
 if(action==='library-prev'||action==='library-next'){search.page+=action==='library-next'?1:-1;$('#library-results').innerHTML=libraryResults();return;}
 if(action==='export-catalog'){const h=['Scenario ID','Title','Sector','Capability','Role','Department','Phase','Facility','Plan','Target minutes','Objective','Status','Version'];download('TRG_starter_catalogue.csv',E.csv([h,...CAT.map(s=>[s.id,s.title,s.sector,s.name,s.role,s.department,s.phase,s.facility,s.plan,s.minutes,s.objective,s.status,s.version])]),'text/csv;charset=utf-8');return;}
 if(action==='campaign'){campaign();return;}
 if(action==='save-campaign'){saveCampaign();return;}
 if(action==='preview-campaign'){previewCampaign(id);return;}
 if(action==='campaign-run'){const c=data.campaigns.find(c=>c.id===id);startRun(c.scenarioId,{...c.config,channel:c.channel});return;}
 if(action==='people-group'){peopleGroup=el.dataset.group;render();return;}
 if(action==='person'){managePerson(id);return;}
 if(action==='save-person'){const x=formObject('#person-form');if(!x)return;const p=data.people.find(p=>p.id===$('#person-form').dataset.id);Object.assign(p,x,{active:!!x.active});audit('Personnel record updated',p.external_id+' · group / role settings');closeDrawer();render();return;}
 if(action==='import-people'){pendingImport=null;importPeople();return;}
 if(action==='people-template'){download('TRG_demo_personnel_template.csv','external_id,name,email,group,role,department,site\r\nDEMO-101,Example Participant,participant101@example.invalid,Incident management team,Duty officer,Command,North Campus\r\n','text/csv;charset=utf-8');return;}
 if(action==='validate-people'){try{pendingImport=E.importPeople($('#people-csv').value,data.people);$('#import-result').innerHTML=`<div class="notice">${pendingImport.accepted.length} accepted for import · ${pendingImport.exceptions.length} exceptions held for review.</div>${pendingImport.exceptions.length?`<div class="mt">${pendingImport.exceptions.map(e=>`<div class="small" style="padding:7px 0">Row ${e.row} · ${esc(e.external_id)}: ${esc(e.reason)}</div>`).join('')}</div>`:''}`;$('#commit-people').disabled=!pendingImport.accepted.length;}catch(e){pendingImport=null;$('#import-result').textContent=e.message;$('#commit-people').disabled=true;}return;}
 if(action==='commit-people'){if(!pendingImport?.accepted.length)return;const n=pendingImport.accepted.length;data.people.push(...pendingImport.accepted);if(pendingImport.exceptions.length)download('TRG_import_exceptions.json',JSON.stringify(pendingImport.exceptions,null,2));audit('Demo personnel imported',n+' accepted; '+pendingImport.exceptions.length+' held as exceptions; no consent inferred');pendingImport=null;closeDrawer();render();toast(n+' fictional records imported.');return;}
 if(action==='add-plan'){addPlan();return;}
 if(action==='save-plan'){const x=formObject('#plan-form');if(!x)return;data.plans.push({...x,id:E.uid('plan'),patterns:[x.pattern],status:'Review required'});audit('Plan excerpt recorded',x.name+' · '+x.version+' · '+x.section);closeDrawer();render();return;}
 if(action==='new-action'){actionForm();return;}
 if(action==='edit-action'){actionForm(id);return;}
 if(action==='action-from-run'){actionForm('',id);return;}
 if(action==='save-action'){saveAction();return;}
 if(action==='report'){go('report/'+id);return;}
 if(action==='export-evidence'){exportEvidence();return;}
 if(action==='integration'){const x=INTEGRATIONS[+el.dataset.index];drawer(x[0],x[1]+' · not connected',`<div class="notice warn">No live connection has been created, tested or implied.</div><p class="mt">${x[2]}</p><h3 class="mt">Required before activation</h3><p class="mt">${x[3]}</p><div class="rule"></div><p>Provisioning, security, owner approval and sandbox verification must pass before a connection can display “Connected.” Secrets must remain server-side. See the source package for the database schema and integration contracts.</p>`,btn('Close','close'));return;}
 if(action==='save-settings'){const x=formObject('#settings-form');if(!x)return;data.settings={...x,hold:!!x.hold,retention:+x.retention};audit('Workspace settings saved','Policy intent updated; live transport remains disabled');render();toast('Workspace settings saved.');return;}
 if(action==='export-workspace'){download('TRG_workspace_'+workspace+'.json',JSON.stringify({exportVersion:1,exportedAt:new Date().toISOString(),mode:backend?'local-demo-database':'browser-demo',workspace,data},null,2));return;}
 if(action==='decision'){advance(el.dataset.choice);return;}
 if(action==='sms-reply'){const reply=$('#sms-reply').value.trim().toUpperCase(),r=data.activeRun;E.record(r,'simulated_sms_reply',{reply});if(reply==='STOP'){r.status='stopped';r.stoppedAt=new Date().toISOString();data.runs.push(r);data.activeRun=null;audit('Exercise stopped','Participant STOP request honored without a failure score');go('overview');return;}if(reply==='HELP'){r.paused=true;E.record(r,'pause',{reason:'Participant requested help'});save();render();toast('Exercise paused. Resume when ready; no real SMS has been sent.');return;}const map={ACK:'ack',DETAILS:'clarify',LATER:'defer'};if(!map[reply]){toast('Use ACK, DETAILS, LATER, HELP or STOP.');save();return;}advance(map[reply]);return;}
 if(action==='narrate'){if(!('speechSynthesis'in window)){toast('This browser does not support speech. The complete transcript is visible.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance((data.activeRun.scenarioSnapshot||findScenario(data.activeRun.scenarioId)).trigger+' '+(data.activeRun.config.variant==='Primary unavailable'?'The primary contact is unavailable; use the designated alternate.':''));u.rate=.92;speechSynthesis.speak(u);E.record(data.activeRun,'local_narration',{channel:'Browser speech synthesis; not a phone call'});save();return;}
 if(action==='submit-task'){const x=formObject('#task-form');if(!x)return;const r=data.activeRun;E.record(r,'task_record',{recipient:x.recipient,checkpoint:x.checkpoint,externalRef:x.externalRef||null,evidenceClass:x.externalRef?'Self-reported external task':'In-platform structured task'});advance(x.choice);return;}
 if(action==='worksheet'){drawer('Training-only action worksheet','This artifact is simulated. Do not submit it to any operational system.',`<div class="notice warn">EXERCISE ONLY · A manual worksheet reference is not externally verified completion.</div><dl class="detail-list"><dt>Exercise run</dt><dd class="mono">${esc(data.activeRun.id)}</dd><dt>Required action</dt><dd>Record verified information, the accountable role and a next checkpoint. Return to the simulation to preserve the reference.</dd></dl><label>Working note<textarea id="worksheet-note" placeholder="Practice here. No external tool is being contacted."></textarea></label>`,btn('Capture worksheet & return','capture-worksheet','primary'));return;}
 if(action==='capture-worksheet'){const note=$('#worksheet-note').value;if(note.trim().length<10){toast('Add a brief working note before capturing the worksheet.');return;}const ref=E.uid('worksheet');E.record(data.activeRun,'simulated_worksheet',{reference:ref,note,verifiedExternally:false});save();closeDrawer();const input=$('#task-form [name="externalRef"]');if(input)input.value=ref;toast('Local worksheet captured. External verification is still not claimed.');return;}
 if(action==='complete-run'){const x=formObject('#brief-form');if(!x)return;try{const r=E.complete(data.activeRun,x);if(!data.runs.some(x=>x.id===r.id))data.runs.push(r);audit('Practice completed',r.scenarioId+' · '+E.summary(r).met+'/3 rule checks; written brief needs review');render();}catch(e){showFormError('#brief-error',e);}return;}
 if(action==='pause'){const r=data.activeRun;r.paused=!r.paused;E.record(r,r.paused?'pause':'resume',{reason:'Participant control'});save();render();return;}
 if(action==='exit-player'){if(data.activeRun?.status==='running'){data.activeRun.paused=true;E.record(data.activeRun,'pause',{reason:'Returned to workspace'});save();}if('speechSynthesis'in window)speechSynthesis.cancel();go('overview');return;}
 if(action==='retest'){const r=data.runs.find(r=>r.id===id),v=['Baseline','Primary unavailable','Conflicting reports'];startRun(r.scenarioId,{...r.config,variant:v[(v.indexOf(r.config.variant)+1)%v.length]},r.id);return;}
 if(action==='export-run'){const r=data.runs.find(r=>r.id===id)||data.activeRun;download('TRG_'+r.scenarioId+'_'+r.id.slice(-8)+'.json',JSON.stringify({recordClass:'Simulation practice; human review required',...r},null,2));return;}
 if(action==='print'){window.print();return;}
}
document.addEventListener('click',e=>{if(e.target.closest('a.skip[href="#main"]')){e.preventDefault();const main=$('#main');if(main){main.setAttribute('tabindex','-1');main.focus({preventScroll:true});main.scrollIntoView({block:'start'});}return;}const b=e.target.closest('[data-action]');if(b){e.preventDefault();Promise.resolve(handleAction(b.dataset.action,b)).catch(err=>{console.error(err);toast('The action could not be completed: '+err.message);});}});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){search.q=e.target.value;search.page=1;$('#library-results').innerHTML=libraryResults();}if(e.target.closest('#brief-form')&&data.activeRun){data.activeRun.draft[e.target.name]=e.target.value;save();}if(e.target.id==='people-csv'){pendingImport=null;const b=$('#commit-people');if(b)b.disabled=true;}});
document.addEventListener('change',async e=>{const id=e.target.id;if(id==='workspace-select'){if(data.activeRun?.status==='running'){data.activeRun.paused=true;E.record(data.activeRun,'pause',{reason:'Workspace switched'});}save();if(backend)await flushDatabase(workspace).catch(()=>{});workspace=e.target.value;storageBlocked=false;try{localStorage.setItem('trg:workspace',workspace);}catch{}data=readLocal();peopleGroup='Everyone';if(backend){try{const r=await fetch('/api/workspaces/'+workspace+'/state'),x=await r.json();if(x.state)data=x.state;else save();}catch{toast('Could not load the local database workspace.');}}render();return;}if(id.startsWith('filter-')){search[id.slice(7)]=e.target.value;search.page=1;$('#library-results').innerHTML=libraryResults();}if(['campaign-group','campaign-channel','campaign-people'].includes(id))$('#audience-preview').innerHTML=audiencePreview($('#campaign-group').value,$('#campaign-channel').value,$('#campaign-group').value==='Selected individuals'?Array.from($('#campaign-people').selectedOptions).map(o=>o.value):null);if(id==='people-file'){const file=e.target.files[0];if(file){if(file.size>1024*1024){toast('Use a CSV smaller than 1 MB.');return;}$('#people-csv').value=await file.text();pendingImport=null;$('#commit-people').disabled=true;}}});
window.addEventListener('hashchange',()=>{closeDrawer();if(data?.activeRun?.status==='running'&&!location.hash.startsWith('#/run')){data.activeRun.paused=true;E.record(data.activeRun,'pause',{reason:'Navigated away from participant view'});save();}render();$('#main')?.focus({preventScroll:true});});
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();if(document.hidden&&data?.activeRun?.status==='running'&&!data.activeRun.paused){data.activeRun.paused=true;E.record(data.activeRun,'pause',{reason:'Page became hidden'});save();if(location.hash==='#/run')render();}});
setInterval(()=>{const now=Date.now(),r=data?.activeRun;if(r?.status==='running'&&!r.paused&&!document.hidden&&location.hash==='#/run'){r.activeMs+=Math.min(now-lastTick,5000);const clockEl=$('#active-clock');if(clockEl)clockEl.textContent=clock(r.activeMs);if(Math.floor(r.activeMs/1000)%5===0)save();}lastTick=now;},1000);
window.addEventListener('beforeunload',()=>{if(data)save();});
// Retire only the prior app's service workers/caches; preserve all old game save keys.
if('serviceWorker'in navigator){navigator.serviceWorker.getRegistrations().then(regs=>regs.forEach(r=>{const name=(r.active?.scriptURL||r.waiting?.scriptURL||'').split('/').pop();if(['trg-sw.js','sw.js'].includes(name))r.update().catch(()=>{});})).catch(()=>{});}
init();
